-- Keep the persisted pre-launch scene below the two-cell blocked far wall.
-- The Office image owns its own surface treatment, so background/dark CSS
-- hints are intentionally no longer part of the scene brand metadata.
UPDATE office_scene
SET scene_json = '{"version":1,"canvas":{"aspect":"16:9","view":"top-down pixel art / slight isometric","grid":{"columns":16,"rows":10}},"brand":{"name":"Envisioning","accentPrimary":"#D6F249","accentSecondary":"#AACC00","style":"clean, quiet, modern, pixel art office, restrained lime accents"},"boundaries":[{"id":"far-wall","type":"wall","position":[0,0],"size":[16,2],"visible":true,"blocksMovement":true,"label":"Far wall"}],"zones":[{"id":"lounge","label":"Lounge","type":"social","position":[5,4],"size":[6,5],"description":"Sofas and a low table for informal work.","anchors":[{"id":"lounge-table","type":"furniture","position":[8,6],"label":"Low table"}]},{"id":"lobby","label":"Waiting room","type":"public","position":[6,8],"size":[4,2],"description":"Arrival area with reception desk and visitor markers.","anchors":[{"id":"reception","type":"furniture","position":[8,9],"label":"Reception desk"}]},{"id":"kitchen","label":"Kitchen","type":"utility","position":[5,2],"size":[6,2],"description":"Counter, stools, and coffee machine.","anchors":[{"id":"coffee-counter","type":"furniture","position":[8,3],"label":"Coffee counter"}]},{"id":"meet","label":"Meet","type":"conversation","position":[0,6],"size":[5,3],"description":"A meeting table for group conversation.","anchors":[{"id":"meeting-table","type":"furniture","position":[2,7],"label":"Meeting table"}]},{"id":"focus","label":"Focus","type":"quiet","position":[0,2],"size":[5,4],"description":"Individual desks and quiet work.","anchors":[{"id":"focus-desk","type":"seat","position":[2,4],"label":"Focus desk"}]},{"id":"create","label":"Create","type":"work","position":[11,2],"size":[5,4],"description":"Workbench, screens, and project materials.","anchors":[{"id":"create-bench","type":"furniture","position":[13,4],"label":"Workbench"}]},{"id":"agents","label":"Agents","type":"agent_area","position":[0,8],"size":[6,2],"description":"AI agent workstations, robots, and terminals.","anchors":[{"id":"agent-desks","type":"furniture","position":[3,9],"label":"Agent workstations"}]},{"id":"think","label":"Think","type":"private","position":[11,6],"size":[5,3],"description":"A quiet room with a round table and glass walls.","anchors":[{"id":"think-table","type":"furniture","position":[13,7],"label":"Round table"}]}]}',
    updated_at = CAST(strftime('%s', 'now') AS INTEGER) * 1000,
    updated_by = 'system:office-boundary-constraint'
WHERE id = 1;
